"""Topic path subscription matcher."""

def _matches_segment(pattern_segment: str, event_segment: str) -> bool:
    """Helper to match a single segment, including '*' wildcard."""
    if pattern_segment == "*":
        return True  # Single wildcard matches any single segment
    return pattern_segment == event_segment

def is_topic_subscribed(subscribed_pattern: str, event_topic: str) -> bool:
    """
    Determines if an event topic matches a subscription pattern,
    respecting hierarchical segment boundaries and wildcards.

    - "orders" matches "orders" and "orders::created", but not "orders_admin".
    - "orders::*" matches "orders::created" but not "orders::created::sub".
    - "orders::**" matches "orders::created" and "orders::created::sub".
    """
    if subscribed_pattern == event_topic:
        return True

    # Handle the case where the subscribed_pattern is a prefix for the event_topic.
    # E.g., "orders" should match "orders::created".
    if event_topic.startswith(subscribed_pattern + "::"):
        return True

    # Handle wildcard matching based on Rule H06
    subscribed_segments = subscribed_pattern.split("::")
    event_segments = event_topic.split("::")

    if not subscribed_segments:
        return not event_segments # An empty pattern only matches an empty topic

    for i, pattern_segment in enumerate(subscribed_segments):
        if pattern_segment == "**":
            # Double wildcard matches zero or more remaining segments.
            # If "**" is the last pattern segment, it matches any remaining event segments.
            return True
        elif i >= len(event_segments):
            # No more event segments to match against the pattern segment.
            # Only matches if current pattern segment is "**" (already handled) or "*" and no more pattern segments.
            return False
        elif not _matches_segment(pattern_segment, event_segments[i]):
            # Current segment does not match, and it's not a wildcard that allows for this mismatch.
            return False

    # All pattern segments matched. Ensure no leftover event segments unless the last pattern segment was "**"
    # (which is handled by the `if pattern_segment == "**"` block).
    # If we reached here, it means all subscribed_segments were matched one-to-one,
    # so the event_segments must not have extra segments unless the last pattern segment was "**".
    return len(subscribed_segments) == len(event_segments)


def clean_topic_segment(topic: str) -> str:
    return topic.strip().lower()

def is_wildcard_subscription(pattern: str) -> bool:
    return pattern.strip() in ("*", "**")
